import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

min_reduce_dim1_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>

__global__ void min_reduce_dim1_kernel(const float* __restrict__ x,
                                        float* __restrict__ out,
                                        int batch, int dim1, int dim2) {
    int c = blockIdx.x * blockDim.x + threadIdx.x;
    int b = blockIdx.y;
    if (c >= dim2) return;
    const float* base = x + (size_t)b * (size_t)dim1 * (size_t)dim2 + c;
    // Use multiple independent accumulators to break the serial dependency
    // chain of fminf reductions, allowing more memory-level parallelism
    // (overlapping loads) while still reading the same coalesced pattern.
    float min0 = FLT_MAX;
    float min1 = FLT_MAX;
    float min2 = FLT_MAX;
    float min3 = FLT_MAX;
    int i = 0;
    int dim1_aligned = dim1 - (dim1 % 4);
    #pragma unroll 4
    for (; i < dim1_aligned; i += 4) {
        float v0 = __ldg(&base[(size_t)(i + 0) * dim2]);
        float v1 = __ldg(&base[(size_t)(i + 1) * dim2]);
        float v2 = __ldg(&base[(size_t)(i + 2) * dim2]);
        float v3 = __ldg(&base[(size_t)(i + 3) * dim2]);
        min0 = fminf(min0, v0);
        min1 = fminf(min1, v1);
        min2 = fminf(min2, v2);
        min3 = fminf(min3, v3);
    }
    for (; i < dim1; ++i) {
        float v = __ldg(&base[(size_t)i * dim2]);
        min0 = fminf(min0, v);
    }
    float min_val = fminf(fminf(min0, min1), fminf(min2, min3));
    out[(size_t)b * (size_t)dim2 + c] = min_val;
}
torch::Tensor min_reduce_dim1_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.dim() == 3, "x must be 3D (batch, dim1, dim2)");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    int batch = x.size(0);
    int dim1  = x.size(1);
    int dim2  = x.size(2);
    auto out = torch::empty({batch, dim2}, x.options());
    const int threads = 256;
    int blocks_x = (dim2 + threads - 1) / threads;
    dim3 blocks(blocks_x, batch);
    min_reduce_dim1_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        batch, dim1, dim2
    );
    return out;
}
"""
min_reduce_dim1_header = r"""
torch::Tensor min_reduce_dim1_cuda(torch::Tensor x);
"""
min_reduce_module = load_inline(
    name="min_reduce_dim1_module",
    cpp_sources=min_reduce_dim1_header,
    cuda_sources=min_reduce_dim1_source,
    functions=["min_reduce_dim1_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized model that performs min reduction over dimension 1 using a custom CUDA kernel.
    Assumes input shape (batch, dim1, dim2) and reduces over dim1.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self.min_reduce = min_reduce_module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if self.dim == 1 and x.dim() == 3 and x.is_cuda and x.dtype == torch.float32:
            x = x.contiguous()
            return self.min_reduce.min_reduce_dim1_cuda(x)
        else:
            return torch.min(x, dim=self.dim)[0]

batch_size = 128
dim1 = 4096
dim2 = 4095

def get_inputs():
    x = torch.rand(batch_size, dim1, dim2).cuda()
    return [x]

